package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.function.common.Hashes;

/**
 * The single definition of an owner's {@code householdId}: a deterministic identifier derived from
 * the owner's last name and postcode, so owners with the same last name and postcode share it
 * automatically. The value is the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode}, where the last name is compared case-insensitively
 * after collapsing runs of whitespace.
 *
 * <p>Because it is a pure function of {@code (lastName, postcode)}, every owner computes its own id
 * independently and members of one household always agree — there is nothing to link or backfill.
 * Shared by {@link AssignHousehold} (which stamps it onto the new owner), {@link RequireUniqueIdentity}
 * (duplicate detection) and {@link AssignOwnerPossibleDuplicate} (soft-match), so every place that
 * keys off the household applies the one rule and they cannot drift apart.
 *
 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
 * expose exactly one public method.
 */
final class HouseholdKey {

    /** Length of the household id: the first 12 hex characters of the SHA-256 digest. */
    private static final int ID_LENGTH = 12;

    private HouseholdKey() {
    }

    /**
     * The deterministic {@code householdId} for the given last name and postcode: the first 12 hex
     * characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. A {@code null} postcode
     * is treated as the empty string.
     */
    static String householdId(String lastName, String postcode) {
        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
        return Hashes.sha256Hex(key).substring(0, ID_LENGTH);
    }

    /**
     * The deterministic {@code householdId} of the given owner — the single home of "which two fields
     * make a household", mirroring {@link IdentityKey#ofOwner}, so callers never re-pluck the tuple.
     */
    static String householdId(Owner owner) {
        return householdId(owner.getLastName(), owner.getPostcode());
    }

    /** Lower-cases and collapses runs of whitespace to a single space for case- and
     *  whitespace-insensitive comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== RequireUniqueIdentity.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The duplicate block of the create-owner pipeline: rejects the request with a 409 (via
 * {@code DuplicateIdentityExceptionHandler}) on an <b>identity duplicate</b> — an exact match on the
 * whole {@link IdentityKey} ({@code telephone|email|householdId}) — because that is the same person.
 *
 * <p>Sharing a household ({@code (lastName, postcode)} through the deterministic
 * {@link HouseholdKey#householdId}) is <em>not</em> in itself a duplicate: a household may have several
 * members, so distinct people ({@link IdentityKey} differs, e.g. a different telephone) in the same
 * household are all allowed. A new member's membershipLevel is then capped relative to the existing
 * members by {@link OwnerHousehold}; it is no longer necessary to declare {@code sharesHousehold}.
 *
 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail}, so the candidate's
 * telephone and email are already normalized. The new owner is not persisted yet, so every match found
 * is another owner.
 */
public class RequireUniqueIdentity {

    public void service(@Val OwnerFieldsDto owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String householdId = HouseholdKey.householdId(owner.getLastName(), owner.getPostcode());
        String candidate = IdentityKey.of(owner.getTelephone(), owner.getEmail(), householdId);
        for (Owner existing : ownerRepository.findAll()) {
            if (!DuplicateCandidates.isCandidate(existing)) {
                continue; // a soft-deleted owner no longer blocks a duplicate or identity match
            }
            if (candidate.equals(IdentityKey.ofOwner(existing))) {
                throw new DuplicateIdentityException(candidate);
            }
        }
    }
}
===== DuplicateCandidates.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The visibility rule shared by the create endpoint's duplicate and identity checks: a soft-deleted
 * owner (see {@link Owner#isDeleted()}) is no longer a match candidate, so both
 * {@link RequireUniqueIdentity} (identity/household duplicate) and {@link AssignOwnerPossibleDuplicate}
 * (soft-match flagging) skip it. Keeping the rule in one place means the two scans that make up the
 * create endpoint's duplicate handling cannot drift apart.
 *
 * <p>Deliberately narrow: this applies only to duplicate/identity matching, not to every scan over
 * existing owners. {@code findById} is unaffected, so {@code GET /api/owners/{id}} still returns a
 * soft-deleted owner, and quota/derived-value scans keep their own (unchanged) semantics.
 */
final class DuplicateCandidates {

    private DuplicateCandidates() {
    }

    /** Whether an existing owner counts as a candidate for duplicate/identity matching. */
    static boolean isCandidate(Owner existing) {
        return !existing.isDeleted();
    }
}
